    void sends_the_authorization_as_a_json_post_to_the_authorizations_endpoint() {
        respond(200, "{\"status\":\"approved\"}");

        gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "eur"));

        assertThat(method.get()).isEqualTo("POST");
        assertThat(path.get()).isEqualTo("/v1/authorizations");
        assertThat(contentType.get()).startsWith("application/json");
        assertThat(body.get()).contains("\"reference\":\"ORD-7\"", "\"amount\":12.50", "\"currency\":\"EUR\"");
    }

    @Test
    void an_approved_answer_is_approved() {
        respond(200, "{\"status\":\"approved\"}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_declined() {
        respond(200, "{\"status\":\"declined\"}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unknown_status_is_never_treated_as_approved() {
        respond(200, "{\"status\":\"pending\"}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_missing_status_is_never_treated_as_approved() {
        respond(200, "{}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void additional_fields_in_the_answer_are_tolerated() {
        respond(200, "{\"status\":\"approved\",\"id\":\"abc\",\"extra\":{\"a\":1}}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_402_refusal_is_a_decline() {
        respond(402, "{\"error\":\"card_refused\"}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_refusal_without_a_body_is_a_decline() {
        respond(402, "");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_rejected_request_is_reported_rather_than_treated_as_a_decision() {
        respond(400, "{\"error\":\"bad_request\"}");

        assertThatThrownBy(this::authorize).isInstanceOf(IllegalStateException.class).hasMessageContaining("400");
    }

    @Test
    void a_provider_failure_is_reported_rather_than_treated_as_a_decision() {
        respond(503, "");

        assertThatThrownBy(this::authorize).isInstanceOf(IllegalStateException.class).hasMessageContaining("503");
    }

    private void respond(int status, String responseBody) {
        this.status = status;
        this.responseBody = responseBody;
    }

    private AuthorizationOutcome authorize() {
        return gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "EUR"));
    }
}
